package receipt
import "parcel-receipt-backend/internal/writer"
func Issue(code string) string { return writer.Current().Put(code) }

files.internal/writer/contract.go:
package writer
type Backend interface { Put(string) string }
type diskWriter struct{}
type memoryWriter struct{}

files.internal/writer/platform_linux.go:
//go:build linux

package writer
func Current() Backend { return diskWriter{} }

files.internal/writer/platform_other.go:
//go:build !linux

package writer
func Current() Backend { return memoryWriter{} }

files.internal/writer/legacy.go:
package writer
type legacyWriter struct{}
func (legacyWriter) Put(code string) string { return "legacy-receipt:" + code }
func Old() Backend { return legacyWriter{} }
